files.content:
html {
  height: 100%;
}

body {
  display: grid;
  place-items: center;
  min-width: 360px;
  height: inherit;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

h2 {
  text-transform: uppercase;
}

.text-block {
  width: 90%;
  margin: auto;
  padding: 40px;
  background-color: #fff;
}
.text-block p:not(:last-child) {
  margin-bottom: 20px;
}
